def mru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.

    The wrapper memoizes the results of the function with a size-limited
    LRU (Least Recently Used) cache.  If `typ` is `True`, cache keys
    are calculated using the function name and `repr` of the full
    argument and keyword argument tuple; otherwise, cache keys are
    calculated using the function name and USE (updated) argument values.

    """
    def decorator(func):
        if maxsize is None:
            return func

        if sys.version_info >= (3, 6):
            cache = functools.lru_cache(maxsize, typed=typed)
        else:
            cache = functools.lru_cache(maxsize, typed=typed)

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            key = (func, args, kwargs) if typed else (func, args)
            try:
                return cache[key]
            except KeyError:
                pass  # key not found
            result = func(*args, **kwargs)
            try:
                cache[key] = result
            except ValueError:
                pass  # value too large
            return result

        wrapper.cache = cache  # make cache available for introspection or manual cleanup
        return wrapper

    return decorator

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    def decorator(func):
        if maxsize < 0 or not callable(func):
            raise ValueError("maxsize must be a positive integer and func must be callable.")
        cache_by_key = {}
        queue = deque()
        def wrapper(*args, **kwargs):
            key = (args, frozenset(kwargs.items())) if typed else args
            if key not in cache_by_key:
                cache_by_key[key] = func(*args, **kwargs)
                queue.append(key)
            else:
                queue.remove(key)
                queue.append(key)
            if len(queue) > maxsize:
                # remove and return the least frequently used key
                key, val = queue.popleft()
                del cache_by_key[key]
            return cache_by_key[key]
        return wrapper
    return decorator

