    if not isinstance(fixity, dict):
        raise TypeError("Fixity must be a dictionary")

    if not isinstance(manifest_files, list):
        raise TypeError("Manifest files must be a list")

    if "fixity" not in fixity:
        raise KeyError("Fixity block not found in inventory")

    for file_name, checksum in fixity["fixity"].items():
        if file_name not in manifest_files:
