def parse_frequency(frequency):
    if frequency is None or frequency.strip().lower() == "always":
        return None
    import re
    pattern = r"^(\d+)\s*(second[s]?|minute[s]?|hour[s]?|day[s]?|week[s]?|month[s]?|year[s]?)$"
    m = re.match(pattern, frequency)
    if m:
        num, unit = m.groups()
        if unit == "second":
            return datetime.timedelta(seconds=int(num))
        elif unit == "minute":
            return datetime.timedelta(minutes=int(num))
        elif unit == "hour":
            return datetime.timedelta(hours=int(num))
        elif unit == "day":
            return datetime.timedelta(days=int(num))
        elif unit == "week":
            return datetime.timedelta(weeks=int(num))
        elif unit == "month":
            return datetime.timedelta(days=int(num*31))
        elif unit == "year":
            return datetime.timedelta(days=int(num*365))
    else:
        raise ValueError("unable to parse frequency {}".format(frequency))

