    """validates that spec (YAML) content has all required fields

    :param spec_content: content of spec file
    :raise IRValidatorException: when mandatory data
    is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """
    if spec_content is None:
        raise IRValidatorException("Spec content is required")
    try:
        spec_data = yaml.load(spec_content, Loader=Loader)
    except yaml.YAMLError as e:
        raise IRValidatorException("Invalid YAML content: " + str(e))
    if mandatory_fields - set(spec_data.keys()) != set():
        raise IRValidatorException("Mandatory data (%s) is missing in spec file" % (", ".join(mandatory_fields - set(spec_data.keys()))))
    return spec_data

def validate_from_file(cls, yaml_file=None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """
    if not yaml_file:
        raise ValueError("YAML file must be provided")

    try:
        with yaml_file.open() as f:
            data = yaml.load(f)
    except Exception as e:
        raise IRValidatorException(f"Error loading YAML file: {e}")

    required_fields = ["some", "required", "fields"]
    for field in required_fields:
        if field not in data:
            raise IRValidatorException(f"Mandatory field {field} missing in YAML file")

    return data

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    if not parser_dict.get('include') or not parser_dict['include'].get('groups'):
        return
    include_groups = parser_dict['include']['groups']
    for group in include_groups:
        included_dict = self._lookup_group(group)
        if included_dict is None:
            raise ValueError(f"Invalid include group: '{group}'")
        parser_dict.update(included_dict)

    # Remove include directive
    del parser_dict['include']

def get_spec_defaults(self):
        """Resolve arguments' values from spec and other sources."""
        resolved_defaults = {}
        for arg in self.args:
            # Check if the argument has a default value
            if not isinstance(arg.default, NoDefault):
                resolved_defaults[arg.name] = arg.default
            # Check if the argument is a dictionary option
            elif isinstance(arg, DictOption):
                # Check if the argument's scheme has a default value
                if not isinstance(arg.scheme.default, NoDefault):
                    resolved_defaults[arg.name] = arg.scheme.default
                # Check if the arg's scheme contains a spec
                elif arg.scheme.spec:
                    resolved_defaults[arg.name] = arg.scheme.spec
        return resolved_defaults

