def complex_type_factory(type_name, spec_option):
    if type_name == 'config':
        return configure_type(spec_option['choices'], spec_option['config'])
    elif type_name == 'bool':
        return bool_type
    elif type_name == 'str':
        return str_type
    elif type_name == 'int':
        return int_type
    elif type_name == 'float':
        return float_type
    elif type_name == 'Dict':
        return dict_type
    else:
        raise ValueError(f"Invalid argument type: {type_name}")

def configure_type(choices, config):
    """Configure the argument type

    :param choices: the list of available choices
    :param config: configuration of the type
    :return: the argument type instance
    """
    type = config['type']
    required = config['required']
    default = config['default']
    help = config['help']
    return type(choices, default=default, required=required, help=help)

