def get_nested_custom_and_control_args(self, args):
    control_args = {}
    nested_args = {}
    custom_args = {}

    for arg in args:
        if arg.startswith('--'):
            control_args[arg] = args[arg]
        elif arg.startswith('nested.'):
            key = arg.replace('nested.', '')
            nested_args[key] = args[arg]
        elif arg.startswith('custom.'):
            key = arg.replace('custom.', '')
            custom_args[key] = args[arg]

    return control_args, nested_args, custom_args

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if not extra_vars:
        return vars_dict
    if vars_dict:
        if isinstance(extra_vars, list):
            if isinstance(vars_dict, dict):
                for item in extra_vars:
                    key, value = item.split('=')
                    vars_dict[key] = value
            elif isinstance(vars_dict, list):
                for item in extra_vars:
                    key, value = item.split('=')
                    for var_dict in vars_dict:
                        var_dict[key] = value
        else:
            raise ValueError('Invalid extra-vars type: {}'.format(type(extra_vars)))
    else:
        raise ValueError('Invalid variables to merge: {}'.format(vars_dict))
    return vars_dict

